function element(node){if(node.closest?.('.language-switcher,[translate="no"]'))return;for(const attr of ['aria-label','alt','title','placeholder'])if(node.hasAttribute?.(attr)){const source=node.getAttribute(attr),previous=attributeValues.get(node)||{};if(previous[attr]===source)continue;const value=translate(source);previous[attr]=value;attributeValues.set(node,previous);if(value!==source)node.setAttribute(attr,value)}}
function walk(root){if(root.nodeType===3){textNode(root);return}if(root.nodeType!==1&&root.nodeType!==9)return;element(root);root.querySelectorAll?.('[aria-label],[alt],[title],[placeholder]').forEach(element);const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walker.nextNode())textNode(walker.currentNode);links(root)}
function selector(){const bar=document.createElement('nav');bar.className='language-switcher';bar.setAttribute('aria-label','Language');const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Language · '+supported[lang][0];details.append(summary);const list=document.createElement('div');for(const [code,[name]] of Object.entries(supported)){const a=document.createElement('a'),u=new URL(location.href);u.searchParams.set('lang',code);a.href=u.href;a.lang=code;a.hreflang=code;a.textContent=name;if(code===lang)a.setAttribute('aria-current','true');a.addEventListener('click',()=>{try{localStorage.setItem('mediterranean-language',code)}catch{}});list.append(a)}details.append(list);bar.append(details);const announcement=document.querySelector('.announcement');if(announcement)announcement.after(bar);else document.body.prepend(bar);document.addEventListener('click',e=>{if(!bar.contains(e.target))details.open=false});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&details.open){details.open=false;summary.focus()}})}
async function start(){selector();const u=new URL(location.href);u.searchParams.set('lang',lang);originalHistory.replaceState(history.state,'',u.href);if(lang==='de'){links(document);new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes)links(node)}).observe(document.body,{childList:true,subtree:true});document.dispatchEvent(new Event('language-ready'));return}try{const response=await fetch('./locales/'+lang+'.json?v=20261119-map-copy');if(!response.ok)throw Error('Language file unavailable');dict=Object.assign(await response.json(),brandCopy[lang],commerceCopy[lang]);api.dictionary=dict;const keys=Object.keys(dict).filter(k=>k.length>=3&&!protectedNames.has(k)).sort((a,b)=>b.length-a.length);pattern=new RegExp(keys.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'gu');walk(document);const observer=new MutationObserver(records=>{for(const record of records){if(record.type==='characterData')textNode(record.target);else if(record.type==='attributes')element(record.target);else for(const node of record.addedNodes)walk(node)}});observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','alt','title','placeholder']});document.dispatchEvent(new Event('language-ready'))}catch(error){document.documentElement.lang='de';const note=document.createElement('p');note.className='language-error';note.setAttribute('role','status');note.textContent='Die gewählte Sprache konnte nicht geladen werden. Bitte lade die Seite erneut. / The selected language could not be loaded. Please reload.';document.querySelector('.language-switcher').after(note);document.dispatchEvent(new Event('language-error'))}}
